import{_ as t,c as s,o,j as n,Y as i,t as r}from"./chunks/framework.D-NV0Bun.js";const b=JSON.parse('{"title":"git-prune | x-cmd man (git man1) | Prune all unreachable objects from the object database","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-prune - Prune all unreachable objects from the object database","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-prune | x-cmd man (git man1) | Prune all unreachable objects from the object database"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-prune - Prune all unreachable objects from the object database"}]]},"headers":[],"params":{"isMan":true,"man":"git-prune","category":"git man1","desc":"Prune all unreachable objects from the object database"},"relativePath":"git/man1/git-prune.md","filePath":"git/man1/[man].md"}'),l={name:"git/man1/git-prune.md"},p={class:"visually-hidden"};function h(a,e,c,d,u,g){return o(),s("div",null,[n("h1",p,r(a.$params.man),1),e[0]||(e[0]=i(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-prune - Prune all unreachable objects from the object database</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prune</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-n] [-v] [--progress] [--expire </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">time</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] [--] [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">head</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><blockquote><p><br> &gt; <strong>Note</strong></p><p><br> &gt; In most cases, users should run <em>git gc</em>, which calls <em>git prune</em>. See the section &quot;NOTES&quot;, below.</p></blockquote><p>This runs <em>git fsck --unreachable</em> using all the refs available in <strong>refs/</strong>, optionally with additional set of objects specified on the command line, and prunes all unpacked objects unreachable from any of these head objects from the object database. In addition, it prunes the unpacked objects that are also found in packs by running <em>git prune-packed</em>. It also removes entries from .git/shallow that are not reachable by any ref.</p><p>Note that unreachable, packed objects will remain. If this is not desired, see <strong>git-repack</strong>(1).</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>-n, --dry-run</p><blockquote><p>Do not remove anything; just report what it would remove.</p></blockquote><p>-v, --verbose</p><blockquote><p>Report all removed objects.</p></blockquote><p>--progress</p><blockquote><p>Show progress.</p></blockquote><p>--expire &lt;time&gt;</p><blockquote><p>Only expire loose objects older than &lt;time&gt;.</p></blockquote><p>--</p><blockquote><p>Do not interpret any more arguments as options.</p></blockquote><p>&lt;head&gt;...</p><blockquote><p>In addition to objects reachable from any of our references, keep objects reachable from listed &lt;head&gt;s.</p></blockquote><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>To prune objects not used by your repository or another that borrows from your repository via its <strong>.git/objects/info/alternates</strong>:</p><blockquote><pre><code>$ git prune $(cd ../another &amp;&amp; git rev-parse --all)
</code></pre></blockquote><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><p>In most cases, users will not need to call <em>git prune</em> directly, but should instead call <em>git gc</em>, which handles pruning along with many other housekeeping tasks.</p><p>For a description of which objects are considered for pruning, see <em>git fsck</em>&#39;s --unreachable option.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>git-fsck</strong>(1), <strong>git-gc</strong>(1), <strong>git-reflog</strong>(1)</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,31))])}const k=t(l,[["render",h]]);export{b as __pageData,k as default};
